INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & signature', '[["Invoice format", "XML — the State Tax Service publishes the file-format specification and sample templates"], ["Language", "Azerbaijani, required by Cabinet Decision No. 26"], ["Signature", "Enhanced electronic signature, mandatory in both online and offline modes"], ["Signing mechanisms", "ASAN İMZA (mobile SIM-based), e-İmza certificate, SİMA Token, or the ASAN DOC client"], ["Container formats", ".adoc and .edoc"], ["European standards", "Not EN 16931; Azerbaijan is not a Peppol authority"]]', 'The absence of EN 16931 and Peppol alignment is asserted by one secondary source and corroborated by silence elsewhere; no primary source addresses it either way.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '"Offline mode" does not mean what it sounds like', NULL, NULL, 'Azerbaijan offers two modes, and the naming misleads people into thinking one of them lets you issue invoices outside the state system. It does not. In online mode you authenticate to the İnternet Vergi İdarəsi portal with an enhanced electronic signature and compose and send in real time. In offline mode you download eFP — Elektron Faktura hazırlama Proqramı — compose and package invoices with no internet connection, sign the package, and then upload it to the portal, at which point the State Tax Service assigns the series and number and emails confirmation. eFP is a preparation tool, not an issuance channel. There is no legally valid e-qaimə that never touches the State Tax Service, because the invoice''s identity — its series and number — is state-issued rather than taxpayer-issued.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Scope, thresholds and deadlines', '[["B2B", "Mandatory and universal — all taxpayers, from 1 January 2018"], ["B2G", "In scope; public bodies are recipients like any registered taxpayer"], ["B2C", "Out of scope as a rule — retail runs on new-generation cash registers — but a consumer may request an e-invoice in a retail or catering transaction"], ["Goods", "Invoice on the same day as delivery"], ["Services", "Within 5 days — except the two 2026 carve-outs below"], ["International transport (from 2026)", "Before the transport begins"], ["Continuous services (from 2026)", "Monthly, at the start of each calendar month''s service, regardless of the billing cycle"], ["Advance payments", "On the day the advance is received"], ["Buyer confirmation", "5 days to confirm or return for correction; silence auto-confirms"], ["Corrections", "Until the 20th of the month following the reporting month"]]', 'B2G scope is inferred: it is asserted by two secondary sources and nowhere carved out, but no primary source explicitly names it.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'Registration at issuance', 'An e-qaimə moves through this sequence in both online and offline modes:', 'The State Tax Service is inside the transaction in real time — but it numbers and records the invoice rather than approving it, and the decisive validation is the buyer''s, or their silence.');
