INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 Three sources, three different labels for the same system', NULL, NULL, 'Anyone researching Azerbaijan will hit a naming problem, so it is worth stating openly. One compliance source calls this a post-audit reporting model and explicitly not pre-clearance. A second calls it "post-audit clearance", which is internally contradictory. A third calls it a clearance model. All three describe the same mechanism. This page does not adopt any of those labels, because clearance overstates what happens and post-audit understates it. What is actually true, from primary sources: the invoice cannot exist outside the state system, its identity is state-issued, it is recorded in AVİS at issuance, and the system validates the counterparty tax ID and computes VAT automatically — but no tax officer or rules engine approves the substance of the invoice as a condition of its validity, and a passive counterparty auto-approves it after five days. That is registration-at-issuance, and describing it in a sentence serves a reader better than forcing it into a one-word category. One further caution: a 2025 industry article claims Azerbaijan mandated e-invoicing in 2010 under Tax Code Article 2. That is wrong — Article 2 concerns the basis of tax legislation, and the operative provision is Article 71-1, inserted for 1 April 2017. It is named here so a future reader does not reintroduce it from a search result.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Penalties escalate within a calendar year — and catch the buyer too', NULL, NULL, 'The figures in the table above come from the State Tax Service''s own 2025 booklet on financial sanctions. Three features are worth drawing out. First, the escalation is per calendar year and resets: 10% for the first instance, 20% for the second, 40% for the third and beyond. Second, Article 58.8.2 charges the buyer, not the seller, where goods are held without the required invoices — so both sides of a transaction carry exposure, which is unusual and makes counterparty compliance a commercial concern rather than someone else''s problem. Third, the State Tax Service has actively policed the B2B/B2C boundary: in July 2020 it publicly warned that wholesale transactions requiring an e-invoice were being disguised as retail point-of-sale sales by ringing implausibly large amounts through cash registers, and confirmed that Article 58.13 sanctions apply to that behaviour.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Two carve-outs, and one penalty that does not exist', NULL, NULL, 'Late submission of an advance-payment electronic invoice specifically does not attract a financial sanction, unlike ordinary electronic invoices — a genuine and slightly odd differentiator, sourced to Azerbaijani professional tax portals rather than statute. Separately, the 2017 State Tax Service presentation routes some e-invoice-related sanctions through Articles 194.2.3 and 194.2.8 at 5-10% for undisclosed funds, in an excise context. And one thing to state plainly rather than imply: no penalty could be sourced for merely late issuance of an ordinary electronic invoice, as distinct from non-issuance. The sanction articles are framed around supplying goods without an e-invoice. This page does not claim a late-filing penalty exists, because it could not be shown to.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔗 Related, but deliberately not shown as an e-invoicing milestone', NULL, NULL, 'From 23 August 2026, non-resident suppliers of electronic services to Azerbaijani consumers must register for VAT and charge 18% once annual Azerbaijan-source gross sales exceed the manat equivalent of USD 10,000, replacing a voluntary-registration and withholding arrangement. This is a VAT-registration obligation, not an e-invoicing one — non-residents do not issue Azerbaijani electronic invoices at all — so this tracker does not record it as a mandate milestone. It is worth knowing for a second reason: a professional-services alert in April 2025 forecast this change for 1 January 2026 with no threshold, noting the enabling legislation had not been adopted. The law that actually passed moved the date to August 2026 and added the USD 10,000 threshold. A useful reminder of why this site verifies against what was enacted rather than what was expected. Separately, from 1 January 2026 a new Article 155.1-1 applies a 0.5 coefficient to cashless point-of-sale receipts when testing the VAT registration threshold, so card turnover counts at half value — meaning a business can run roughly AZN 400,000 of card sales before crossing the AZN 200,000 line.');
