INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Buyer holds goods without the required e-invoices or purchase documents (Art. 58.8.2)', '10% / 20% / 40% of the value of the goods, escalating on repeat within a calendar year', 'No cap published');
