INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Re-cut your invoicing cycle for continuous services', 'This is the most urgent item on the page. Since 1 January 2026, regularly and continuously supplied services — security, cleaning, utilities, subscriptions, and most SaaS — must be invoiced monthly, at the start of each month''s service, even where your contract bills quarterly or annually. If your ERP is still following a blanket five-day service rule, it is following a rule that no longer applies.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Move transport invoicing ahead of the transport', 'International transport services must now be invoiced by the time the transport begins, not within five days of it. For freight and logistics operators this reverses the usual order of operations and needs a process change, not just a date field.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Get an enhanced electronic signature and a portal account', 'You need ASAN İMZA, an e-İmza certificate or a SİMA Token, plus access to the İnternet Vergi İdarəsi portal. If you plan to prepare invoices in bulk offline, install eFP as well — but remember it prepares rather than issues.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch your inbound invoices, not just your outbound ones', 'Article 58.8.2 penalises the buyer for holding goods without the required invoices, at the same escalating 10/20/40% rates. Chase suppliers who have not issued, and use the five-day confirmation window actively — silence counts as confirmation, so an unreviewed invoice becomes an accepted one.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'AZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Re-check your VAT registration position for 2026', 'New Article 155.1-1 counts cashless point-of-sale receipts at half value when testing the AZN 200,000 registration threshold, so a retail or services business can now run roughly AZN 400,000 of card turnover before mandatory registration. If you were close to the line, you may no longer be.');
